import { render } from '@solidjs/web';
import { createSignal, Show, onSettled } from 'solid-js';
import './styles.css';

function App() {
  const [visible, setVisible] = createSignal(true);
  let box;
  let animation;
  onSettled(() => () => animation?.cancel());
  async function toggle() {
    animation?.cancel();
    if (visible()) {
      animation = box.animate(
        [
          { opacity: 1, transform: 'translateX(0)' },
          { opacity: 0, transform: 'translateX(30px)' },
        ],
        { duration: 350 },
      );
      try {
        await animation.finished;
        setVisible(false);
      } catch {}
    } else setVisible(true);
  }
  function capture(element) {
    box = element;
    animation = box.animate(
      [
        { opacity: 0, transform: 'translateX(-30px)' },
        { opacity: 1, transform: 'translateX(0)' },
      ],
      { duration: 350 },
    );
  }
  return (
    <>
      <h1>DOM animations</h1>
      <button
        onClick={() => {
          void toggle();
        }}
      >
        Toggle
      </button>
      <Show when={visible()}>
        <div class="box" ref={capture}>
          Solid 2 owns the view; the browser animates its elements.
        </div>
      </Show>
    </>
  );
}

render(() => <App />, document.getElementById('app'));

.box {
  margin: 20px 0;
  padding: 30px;
  background: #335d92;
  color: white;
  border-radius: 8px;
  max-width: 400px;
}
